import{_ as r,o as t,c as a,an as o}from"./chunks/framework.1NXF-jwl.js";const s="/AtmosTransport.jl/dev/assets/AtmosTransport_banner.DOW-u6wk.png",h=JSON.parse('{"title":"AtmosTransport.jl","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function i(l,e,p,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="AtmosTransport.jl" tabindex="-1">AtmosTransport.jl <a class="header-anchor" href="#AtmosTransport.jl" aria-label="Permalink to &quot;AtmosTransport.jl {#AtmosTransport.jl}&quot;">​</a></h1><p><img src="'+s+'" alt=""></p><p>A Julia-based, GPU-portable atmospheric tracer transport model for offline chemistry / chemical-transport applications. Designed for <strong>mass-conserving</strong> advection, convection, and boundary-layer diffusion on <strong>lat-lon, reduced Gaussian, and cubed-sphere</strong> grids, driven by <strong>ERA5</strong> or <strong>GEOS</strong> met data, with a clean separation between offline preprocessing and runtime stepping.</p><h2 id="At-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#At-a-glance" aria-label="Permalink to &quot;At a glance {#At-a-glance}&quot;">​</a></h2><ul><li><p><strong>Multi-grid</strong>: regular lat-lon, reduced Gaussian, cubed-sphere (gnomonic and GEOS-native panel conventions).</p></li><li><p><strong>Multi-source</strong>: ERA5 spectral (vorticity / divergence / log-PS GRIB), GEOS-IT C180 native NetCDF, GEOS-FP C720 native hourly NetCDF, and a preview MERRA-2 wind-derived cubed-sphere preprocessor.</p></li><li><p><strong>GPU-portable</strong>: single codebase for CPU, NVIDIA CUDA, and Apple Silicon Metal via <a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions.jl</a>. Metal is restricted to <code>Float32</code> runtime numerics.</p></li><li><p><strong>Mass-conserving</strong>: dry-basis air-mass bookkeeping, with <strong>write-time replay gates</strong> in the preprocessor and <strong>opt-in load-time replay validation</strong> at runtime.</p></li><li><p><strong>Operator-modular</strong>: every physics operator is behind an abstract type with a <code>No&lt;Operator&gt;</code> no-op default; swap schemes via type dispatch.</p></li><li><p><strong>TM5-faithful core</strong>: Russell-Lerner slopes advection with Strang splitting; CMFMC convection (GCHP-style for GEOS sources) and TM5 convection (entrainment / detrainment for ERA5 sources) sharing one runtime carrier.</p></li></ul><h2 id="When-to-use-AtmosTransport" tabindex="-1">When to use AtmosTransport <a class="header-anchor" href="#When-to-use-AtmosTransport" aria-label="Permalink to &quot;When to use AtmosTransport {#When-to-use-AtmosTransport}&quot;">​</a></h2><ul><li><p>You have offline meteorological fields (winds, mass fluxes, surface pressure, optionally moist physics) and want to integrate one or more passive or reactive trace gases at coarse-to-medium resolution.</p></li><li><p>You need GPU performance with bit-reproducible CPU fallback.</p></li><li><p>You want a model where the mass-conservation contract is explicit at every layer (preprocessor output ↔ runtime state ↔ snapshot output).</p></li></ul><p>If you need a fully online dynamical core (LES, GCM), look elsewhere — AtmosTransport assumes a precomputed mass-flux time series.</p><h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><p>The recommended reading order is:</p><ol><li><p><a href="./getting_started/installation">Installation</a> and <a href="./getting_started/quickstart">Quickstart</a>.</p></li><li><p><a href="./concepts/grids">Concepts</a> — grids, state, operators, and binaries.</p></li><li><p><a href="./preprocessing/overview">Preprocessing</a> — raw meteorology to transport binaries.</p></li><li><p><a href="./theory/mass_conservation">Theory and verification</a>.</p></li><li><p><a href="./api/">API reference</a>.</p></li></ol><p>The most useful repository entry points are:</p><ul><li><p><code>scripts/run_transport.jl</code> — runtime driver script.</p></li><li><p><code>scripts/preprocessing/preprocess_transport_binary.jl</code> — preprocessing CLI.</p></li><li><p><code>scripts/diagnostics/inspect_transport_binary.jl</code> — inspect a transport binary.</p></li><li><p><code>config/runs/</code> — example run configurations (TOML).</p></li><li><p>The repository <code>README.md</code> and <code>docs/reference/</code> pages carry the current status, invariants, and project map.</p></li></ul>',13)])])}const g=r(n,[["render",i]]);export{h as __pageData,g as default};
